import {cubeData} from './nano-models.js?v=20261023-physicscomplete01';
import {enable3D,renderModel,renderDiagram} from './visual.js?v=20261023-physicscomplete01';
const text=(x,y,s,size=12)=>`<text x="${x}" y="${y}" fill="#d4dfe7" font-family="sans-serif" text-anchor="middle" font-size="${size}">${s}</text>`;
const svg=(art,label)=>`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="${label}">${art}</svg>`;
export function showNanoScale(exponent=1){const nm=10**exponent;let art='<path d="M45 140H395" stroke="#b7c8d6" stroke-width="2"/>';for(let e=-1;e<=4;e++){const x=45+(e+1)*70;art+=`<path d="M${x} 130V150" stroke="#b7c8d6"/>`+text(x,173,10**e+'',11);}const x=45+(exponent+1)*70;art+=`<circle cx="${x}" cy="140" r="8" fill="#ed8b78"/>`+text(220,70,`${nm} nm = ${nm*1e-9} m`,18)+text(220,205,'Diameter / nm · logarithmic ruler',12)+text(220,250,'Equal gaps mean ×10 · not a photograph',11);renderDiagram('Orders of size',`${nm} nm`,svg(art,'Logarithmic ruler from 0.1 to 10000 nm with marker at '+nm+' nm'),'SIZE COMPARISON · LOGARITHMIC');}
export function showNanoCubes(n=1){const data=cubeData(10,n),atoms=[];const size=3/n,gap=.13;for(let x=0;x<n;x++)for(let y=0;y<n;y++)for(let z=0;z<n;z++)atoms.push(['Cube',(x-(n-1)/2)*(size+gap),(y-(n-1)/2)*(size+gap),(z-(n-1)/2)*(size+gap)]);const flat=svg(`<path d="M135 90L245 65L315 110L205 140Z" fill="#ed8b78"/><path d="M135 90V195L205 240V140Z" fill="#b7c8d6"/><path d="M205 140L315 110V210L205 240Z" fill="#304b61"/>`+text(220,32,`One particle · side ${data.side} nm`,16)+text(220,274,`Set: ${data.count} cube${data.count===1?'':'s'} · all six faces exposed` ,10),`${data.count} separate cubes each of side ${data.side} nm; total material volume 1000 cubic nm`);enable3D();renderModel({name:n===1?'One cube of material':'The same material, divided',formula:`${data.count} × ${data.side} nm cubes`,aria:`${data.count} cubes, each side ${data.side} nm. Same total volume of material; separated to expose all faces. Rotate with arrows.`,zoom:14,kicker:'SCHEMATIC IDEAL CUBES · NOT ATOMS · ARTIFICIAL GAPS',atoms,bonds:[],cubeSize:size,diagram:flat});}
export function showNanoEvidence(){renderDiagram('Evaluate the evidence','Benefit · exposure · uncertainty','<div class="diagram-card"><span class="eyebrow">RESEARCH QUESTIONS</span><p>What useful effect was measured?</p><p>Who or what could be exposed?</p><p>Which effects were not measured?</p><p>What further test would help?</p></div>','FICTIONAL CASE DATA · NOT PRODUCT GUIDANCE');}
export function showNano(kind){if(kind==='scale')showNanoScale();else if(kind==='evidence')showNanoEvidence();else showNanoCubes(kind==='split'?2:1);}
